<?php
declare(strict_types=1);
ob_start();require dirname(__DIR__).'/portal-private/bootstrap.php';$p=getenv('PORTAL_CONFIG_FILE');if(!$p||!str_ends_with($p,'config.test.php'))throw new RuntimeException('Solo pruebas.');$c=require$p;if(!str_ends_with($c['db_name'],'_test'))throw new RuntimeException('Solo base de pruebas.');$app=portal_app();$db=$app->db();$n=0;
function actor(string$name):void{global$db;$s=$db->prepare('SELECT id,auth_version FROM pisco_users WHERE username=?');$s->execute([$name]);$r=$s->fetch();$_SESSION['user_id']=(int)$r['id'];$_SESSION['auth_version']=(int)$r['auth_version'];}
function put(array$d):void{global$app;$app->save(['data'=>$d,'revision'=>$app->bootstrap()['revision']]);}
function check(bool$v,string$l):void{global$n;if(!$v)throw new RuntimeException($l);$n++;echo"OK $l\n";}
actor('admin');$full=$app->bootstrap()['data'];
try{foreach(['admisiones','matriculas','becasPeriodos']as$key){actor('admin');$d=$app->bootstrap()['data'];$old=$d[$key][0];foreach($d[$key]as&$r){$r['vigente']=$r['id']===$old['id'];if($r['vigente'])$r['estado']='Publicado';}unset($r);put($d);$d=$app->bootstrap()['data'];$pending=$old;$pending['id']='deep-publish-'.bin2hex(random_bytes(4));$pending['anio']=2094;if($key==='matriculas')$pending['periodo']='2094-I';$pending['estado']='En revisión';$pending['vigente']=true;$d[$key][]=$pending;put($d);$after=$app->bootstrap()['data'];check(PortalPolicy::find($after[$key],'id',$old['id'])['vigente']===true,"$key: pendiente conserva el proceso publicado");$d=$after;foreach($d[$key]as&$r)if($r['id']===$pending['id'])$r['estado']='Publicado';unset($r);put($d);$after=$app->bootstrap()['data'];check(PortalPolicy::find($after[$key],'id',$pending['id'])['vigente']===true&&PortalPolicy::find($after[$key],'id',$old['id'])['vigente']===false,"$key: publicar sustituye el vigente de forma coherente");put($full);}}
finally{actor('admin');put($full);}echo"\n$n comprobaciones de publicación aprobadas.\n";ob_end_flush();
